DROP TABLE IF EXISTS `bdt_article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bdt_article` (
  `article_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(300) NOT NULL,
  `slug` varchar(300) NOT NULL COMMENT 'URL-friendly, contoh: festival-baca-desa-teras-2026',
  `excerpt` text DEFAULT NULL COMMENT 'Ringkasan singkat (max 300 karakter)',
  `body` longtext NOT NULL COMMENT 'Isi artikel penuh, mendukung HTML',
  `cover_image` varchar(255) DEFAULT NULL COMMENT 'Path gambar utama artikel',
  `category` enum('berita','kegiatan','pengumuman','resensi','literasi','lainnya') NOT NULL DEFAULT 'berita' COMMENT 'Kategori artikel',
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `publish_date` datetime DEFAULT NULL COMMENT 'Tanggal & jam dipublish (bisa dijadwalkan)',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=tampil di homepage',
  `is_pinned` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=ditempel di atas daftar',
  `created_by` int(11) DEFAULT NULL COMMENT 'FK → user.user_id (SLiMS librarian)',
  `updated_by` int(11) DEFAULT NULL COMMENT 'FK → user.user_id (SLiMS librarian)',
  `biblio_id` int(11) DEFAULT NULL COMMENT 'FK opsional → biblio.biblio_id (SLiMS)',
  `library_id` int(11) DEFAULT NULL COMMENT 'FK opsional → bdt_library.library_id',
  `meta_description` varchar(300) DEFAULT NULL,
  `meta_keywords` varchar(255) DEFAULT NULL,
  `view_count` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`article_id`),
  UNIQUE KEY `slug` (`slug`),
  UNIQUE KEY `uk_slug` (`slug`),
  KEY `idx_status` (`status`),
  KEY `idx_category` (`category`),
  KEY `idx_publish_date` (`publish_date`),
  KEY `idx_is_featured` (`is_featured`),
  KEY `idx_library_id` (`library_id`),
  KEY `idx_biblio_id` (`biblio_id`),
  KEY `idx_created_by` (`created_by`),
  FULLTEXT KEY `ft_title_body` (`title`,`body`,`excerpt`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Artikel, berita, dan kegiatan portal Baca Di Teras';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `bdt_article` WRITE;
/*!40000 ALTER TABLE `bdt_article` DISABLE KEYS */;
INSERT INTO `bdt_article` VALUES (1,'Festival Baca Desa Teras 2026: Merayakan Literasi Bersama','festival-baca-desa-teras-2026','Festival Baca Desa Teras kembali hadir tahun ini dengan berbagai kegiatan menarik yang melibatkan seluruh warga desa.','<p>Festival Baca Desa Teras 2026 akan diselenggarakan pada tanggal 25–27 Juli 2026 di Balai Desa Teras. Festival ini menampilkan berbagai kegiatan seperti pameran buku, lomba membaca, diskusi literasi, dan pertunjukan seni berbasis sastra.</p><p>Acara ini terbuka untuk seluruh masyarakat dan tidak dipungut biaya masuk. Mari bergabung dan rayakan semangat literasi bersama!</p>','/custom/assets/images/event-workshop.png','kegiatan','published','2026-07-15 08:00:00',1,0,NULL,NULL,NULL,1,NULL,NULL,7,'2026-07-15 12:18:47','2026-07-15 13:09:41'),(2,'Koleksi Baru: 50 Judul Buku Pertanian Modern Hadir di Perpustakaan Utama','koleksi-baru-buku-pertanian-modern','Perpustakaan Utama Desa menerima donasi 50 judul buku pertanian modern dari Dinas Pertanian Boyolali.','<p>Kabar baik bagi para petani dan pecinta pertanian di Desa Teras! Perpustakaan Utama Desa kini memiliki koleksi baru berupa 50 judul buku tentang pertanian modern, teknik bercocok tanam ramah lingkungan, dan agribisnis.</p><p>Buku-buku ini merupakan donasi dari Dinas Pertanian Kabupaten Boyolali dan sudah tersedia untuk dipinjam mulai hari ini.</p>','/custom/assets/images/news-featured.png','berita','published','2026-07-10 09:00:00',0,0,NULL,NULL,NULL,1,NULL,NULL,8,'2026-07-15 12:18:47','2026-07-15 13:09:41'),(3,'Workshop Literasi Digital untuk Ibu-Ibu PKK Desa Teras','workshop-literasi-digital-pkk','Taman Baca Komunitas mengadakan workshop literasi digital gratis untuk ibu-ibu anggota PKK di Desa Teras.','<p>Taman Baca Komunitas bekerja sama dengan Pemerintah Desa Teras menyelenggarakan Workshop Literasi Digital yang ditujukan khusus untuk ibu-ibu anggota PKK.</p><p>Workshop ini membahas cara memanfaatkan smartphone untuk kegiatan produktif, menghindari hoaks, dan mengakses layanan perpustakaan digital secara gratis.</p><p>Pendaftaran dapat dilakukan langsung di Taman Baca Komunitas atau melalui WhatsApp di nomor yang tertera.</p>','/custom/assets/images/event-book-club.png','kegiatan','published','2026-07-12 10:00:00',1,0,NULL,NULL,NULL,2,NULL,NULL,3,'2026-07-15 12:18:47','2026-07-15 13:09:41'),(4,'Pengumuman: Perpustakaan Digital Teras Kini Buka hingga Pukul 20.00','pengumuman-perpustakaan-digital-buka-malam','Mulai 1 Agustus 2026, Perpustakaan Digital Teras memperpanjang jam layanan hingga pukul 20.00 WIB.','<p>Demi memberikan layanan yang lebih optimal kepada masyarakat, Perpustakaan Digital Teras mengumumkan perpanjangan jam operasional mulai 1 Agustus 2026.</p><p>Perpustakaan kini melayani pengunjung dari pukul <strong>08.00 hingga 20.00 WIB</strong> pada hari Senin–Jumat, sehingga warga yang bekerja di siang hari tetap dapat mengakses layanan perpustakaan di malam hari.</p>','/custom/assets/images/news-small.png','pengumuman','published','2026-07-13 08:00:00',0,0,NULL,NULL,NULL,3,NULL,NULL,3,'2026-07-15 12:18:47','2026-07-15 13:09:41');
/*!40000 ALTER TABLE `bdt_article` ENABLE KEYS */;
