DROP TABLE IF EXISTS `bdt_migration_map`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bdt_migration_map` (
  `map_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `library_id` int(11) NOT NULL,
  `source_code` varchar(10) NOT NULL,
  `source_database` varchar(64) NOT NULL,
  `source_type` varchar(20) NOT NULL,
  `source_table` varchar(64) NOT NULL,
  `old_id` varchar(100) NOT NULL,
  `target_table` varchar(64) NOT NULL,
  `new_id` varchar(100) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`map_id`),
  UNIQUE KEY `uniq_bdt_migration_source_row` (`source_code`,`source_table`,`old_id`,`target_table`),
  KEY `idx_bdt_migration_library` (`library_id`),
  KEY `idx_bdt_migration_source` (`source_code`),
  KEY `idx_bdt_migration_target` (`target_table`,`new_id`),
  CONSTRAINT `fk_bdt_migration_library` FOREIGN KEY (`library_id`) REFERENCES `bdt_library` (`library_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=39256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `bdt_migration_map` WRITE;
