DROP TABLE IF EXISTS `bdt_village_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bdt_village_profile` (
  `profile_id` int(11) NOT NULL AUTO_INCREMENT,
  `village_name` varchar(150) NOT NULL DEFAULT 'Desa Teras',
  `tagline` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `sejarah` text DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL COMMENT 'Kecamatan',
  `regency` varchar(100) DEFAULT NULL COMMENT 'Kabupaten',
  `province` varchar(100) DEFAULT NULL COMMENT 'Provinsi',
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `whatsapp` varchar(20) DEFAULT NULL,
  `website` varchar(100) DEFAULT NULL,
  `google_maps_url` text DEFAULT NULL COMMENT 'URL embed Google Maps',
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `logo_path` varchar(255) DEFAULT NULL,
  `hero_image_path` varchar(255) DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`profile_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Profil utama Desa Teras (satu baris)';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `bdt_village_profile` WRITE;
/*!40000 ALTER TABLE `bdt_village_profile` DISABLE KEYS */;
INSERT INTO `bdt_village_profile` VALUES (1,'Desa Teras','Portal Literasi Digital Desa Teras','Baca Di Teras merupakan portal literasi digital yang lahir dari semangat komunitas Desa Teras, Boyolali. Kami percaya bahwa membaca adalah jendela dunia yang harus bisa diakses oleh semua kalangan, tanpa terkecuali — dari anak-anak hingga orang tua.','Baca Di Teras berdiri sejak lebih dari 10 tahun lalu sebagai gerakan literasi grassroots yang digagas oleh para tokoh masyarakat Desa Teras. Berawal dari satu rak buku sederhana di teras rumah, kini telah berkembang menjadi jaringan 6 perpustakaan dengan ribuan koleksi.','Jl. Raya Teras, Desa Teras','Teras','Boyolali','Jawa Tengah','+62 271-781000','contact@desateras.id','+62 812-3456-7890','https://desateras.go.id','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3955.034!2d110.648!3d-7.515!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2sTeras%2C+Boyolali!5e0!3m2!1sid!2sid!4v0000000000000',-7.51500000,110.64800000,NULL,NULL,'2026-07-15 12:18:47');
/*!40000 ALTER TABLE `bdt_village_profile` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `biblio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `biblio` (
  `biblio_id` int(11) NOT NULL AUTO_INCREMENT,
  `gmd_id` int(3) DEFAULT NULL,
  `title` text NOT NULL,
  `sor` varchar(200) DEFAULT NULL,
  `edition` varchar(50) DEFAULT NULL,
  `isbn_issn` varchar(32) DEFAULT NULL,
  `publisher_id` int(11) DEFAULT NULL,
  `publish_year` varchar(20) DEFAULT NULL,
  `collation` varchar(100) DEFAULT NULL,
  `series_title` varchar(200) DEFAULT NULL,
  `call_number` varchar(50) DEFAULT NULL,
  `language_id` char(5) DEFAULT 'en',
  `source` varchar(10) DEFAULT NULL,
  `publish_place_id` int(11) DEFAULT NULL,
  `classification` varchar(40) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `image` varchar(100) DEFAULT NULL,
  `file_att` varchar(255) DEFAULT NULL,
  `opac_hide` smallint(1) DEFAULT 0,
  `promoted` smallint(1) DEFAULT 0,
  `labels` text DEFAULT NULL,
  `frequency_id` int(11) NOT NULL DEFAULT 0,
  `spec_detail_info` text DEFAULT NULL,
  `content_type_id` int(11) DEFAULT NULL,
  `media_type_id` int(11) DEFAULT NULL,
  `carrier_type_id` int(11) DEFAULT NULL,
  `input_date` datetime DEFAULT NULL,
  `last_update` datetime DEFAULT NULL,
  `uid` int(11) DEFAULT NULL,
  PRIMARY KEY (`biblio_id`),
  KEY `references_idx` (`gmd_id`,`publisher_id`,`language_id`,`publish_place_id`),
  KEY `classification` (`classification`),
  KEY `biblio_flag_idx` (`opac_hide`,`promoted`),
  KEY `rda_idx` (`content_type_id`,`media_type_id`,`carrier_type_id`),
  KEY `uid` (`uid`),
  KEY `publisher_id` (`publisher_id`),
  FULLTEXT KEY `title_ft_idx` (`title`,`series_title`),
  FULLTEXT KEY `notes_ft_idx` (`notes`),
  FULLTEXT KEY `labels` (`labels`)
) ENGINE=MyISAM AUTO_INCREMENT=400133 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `biblio` WRITE;
