INSERT INTO `setting` VALUES (1,'library_name','s:13:\"Baca Di Teras\";'),(2,'library_subname','s:37:\"Desa Teras, Kecamatan Teras, Boyolali\";'),(3,'template','a:23:{s:5:\\\"theme\\\";s:7:\\\"default\\\";s:3:\\\"css\\\";s:26:\\\"template/default/style.css\\\";s:10:\\\"responsive\\\";s:1:\\\"0\\\";s:23:\\\"classic_library_subname\\\";s:1:\\\"0\\\";s:28:\\\"classic_library_disableslide\\\";s:1:\\\"0\\\";s:24:\\\"classic_slide_transition\\\";s:4:\\\"fade\\\";s:23:\\\"classic_slide_animation\\\";s:4:\\\"none\\\";s:19:\\\"classic_slide_delay\\\";s:4:\\\"5000\\\";s:26:\\\"classic_popular_collection\\\";s:1:\\\"1\\\";s:31:\\\"classic_popular_collection_item\\\";s:1:\\\"6\\\";s:22:\\\"classic_new_collection\\\";s:1:\\\"1\\\";s:27:\\\"classic_new_collection_item\\\";s:1:\\\"6\\\";s:18:\\\"classic_top_reader\\\";s:1:\\\"1\\\";s:18:\\\"classic_suggestion\\\";s:1:\\\"1\\\";s:11:\\\"classic_map\\\";s:1:\\\"1\\\";s:16:\\\"classic_map_link\\\";s:313:\\\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15821.06136268697!2d110.660881!3d-7.546016449999998!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e7a6b9cb90204ab%3A0x5027a76e356cf10!2sTeras%2C%20Kec.%20Teras%2C%20Kabupaten%20Boyolali%2C%20Jawa%20Tengah!5e0!3m2!1sid!2sid!4v1783354861738!5m2!1sid!2sid\\\";s:16:\\\"classic_map_desc\\\";s:323:\\\"<p>Desa Teras merupakan salah satu dari 13 desa di Kecamatan Teras, Kabupaten Boyolali, Jawa Tengah. Terletak strategis di Jalan Boyolali - Solo, wilayah ini berbatasan langsung dengan pusat mobilitas lokal dan terkenal dengan bentang alam persawahan serta sejarahnya.<br>Telp. (021) 9172638<br>Fax. (021) 9172638<br> </p>\\\";s:15:\\\"classic_fb_link\\\";s:45:\\\"https://www.facebook.com/groups/senayan.slims\\\";s:20:\\\"classic_twitter_link\\\";s:34:\\\"https://twitter.com/slims_official\\\";s:20:\\\"classic_youtube_link\\\";s:19:\\\"https://youtube.com\\\";s:22:\\\"classic_instagram_link\\\";s:31:\\\"https://instagram.com/slims.sdc\\\";s:23:\\\"classic_footer_about_us\\\";s:293: